        self.msgId = msgId
        self.recipientUserId = recipientUserId
        self.chatId = chatId
        self.senderUserId = senderUserId
        self.receiptType = receiptType
        self.throughLamport = throughLamport
        self.timestamp = timestamp
        self.hopTtl = hopTtl
        self.expiry = expiry
        self.recipientHint = recipientHint
        self.sealed = sealed
    }
}



extension OutgoingReceiptEnvelope: Equatable, Hashable {
    public static func ==(lhs: OutgoingReceiptEnvelope, rhs: OutgoingReceiptEnvelope) -> Bool {
        if lhs.msgId != rhs.msgId {
            return false
        }
        if lhs.recipientUserId != rhs.recipientUserId {
            return false
        }
        if lhs.chatId != rhs.chatId {
            return false
        }
        if lhs.senderUserId != rhs.senderUserId {
            return false
        }
        if lhs.receiptType != rhs.receiptType {
            return false
        }
        if lhs.throughLamport != rhs.throughLamport {
            return false
        }
        if lhs.timestamp != rhs.timestamp {
            return false
        }
        if lhs.hopTtl != rhs.hopTtl {
            return false
        }
        if lhs.expiry != rhs.expiry {
            return false
        }
        if lhs.recipientHint != rhs.recipientHint {
            return false
        }
        if lhs.sealed != rhs.sealed {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(msgId)
        hasher.combine(recipientUserId)
        hasher.combine(chatId)
        hasher.combine(senderUserId)
        hasher.combine(receiptType)
        hasher.combine(throughLamport)
        hasher.combine(timestamp)
        hasher.combine(hopTtl)
        hasher.combine(expiry)
        hasher.combine(recipientHint)
        hasher.combine(sealed)
