            FfiConverterString.write(v1, into: &buf)
            
        
        case let .InvalidKeyLength(expected,actual):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(expected, into: &buf)
            FfiConverterUInt32.write(actual, into: &buf)
            
        
